    count = [0] * 2
    for char in s:
        count[int(char)] += 1

    if k >= n - 1:
        return ''.join('0' * count[0] + '1' * count[1])

    result = list(s)
    i = 0
    while k > 0 and count[1] > 0:
        if result[i] == '1':
            j = i + 1
            while j < n and result[j] != '0':
                j += 1
            if j < n:
                result[i], result[j] = result[j], result[i]
                k -= j - i - 1
                count[0] += 1
                count[1] -= 1
            else:
                break
        i += 1
    return ''.join(result)

