    n = len(s)
    count_ones = s.count('1')
    if count_ones == 0 or count_ones == n:
        return s

    left_zeros = 0
    right_ones = 0
    for i in range(n):
        if s[i] == '0':
            left_zeros += 1
        else:
            break

    for i in range(n-1, -1, -1):
        if s[i] == '1':
            right_ones += 1
        else:
            break

    swaps_needed = left_zeros + right_ones - 1

    if swaps_needed > k:
        # We need to make some adjustments within the allowed swaps
        remaining_swaps = k - swaps_needed

        # If we have extra swaps, we can distribute them to make the string even smaller
        while remaining_swaps > 0:
