def min_lexicographical_string(n, k, s):
    # Count the number of misplaced pairs
    misplaced_pairs = 0
    for i in range(n - 1):
        if s[i] > s[i + 1]:
            misplaced_pairs += 1

    # If we have enough moves to fix all misplaced pairs, sort the string
    if misplaced_pairs <= k:
        return ''.join(sorted(s))

    # Otherwise, try to fix the smallest misplaced pair
    result = list(s)
    for i in range(misplaced_pairs):
        for j in range(i + 1, n):
            if result[j] < result[i]:
                result[i], result[j] = result[j], result[i]
                break
        else:
            continue
        break

    return ''.join(result)

